71| <body>
72| <div id="wrap">
73|   <canvas id="game"></canvas>
74| </div>
75| <div id="tally">Cailloux : 0</div>
76| <button id="clearBtn">Ratisser le sable</button>
77| 
78| <script>
79| // ---- Bridge helper (verbatim) ----
80| const CARTRIDGE = {
81|   send(type, payload = {}) {
82|     window.parent.postMessage(
83|       { source: "cartridge", v: 1, type, payload },
84|       "*",
85|     );
86|   },
87| };
88| </script>
89| 
90| <script>
91| (function () {
92|   const canvas = document.getElementById("game");
93|   const ctx = canvas.getContext("2d");
94|   const clearBtn = document.getElementById("clearBtn");
95|   const tallyEl = document.getElementById("tally");
96| 
97|   let dpr = Math.max(1, window.devicePixelRatio || 1);
98|   let W = 0, H = 0;
99| 
100|   let paused = false;
101|   let running = false; // becomes true after first tap (start)
102| 
103|   const pieces = []; // {x,y,r,rot,shade}
104|   let tally = 0;
105| 
106|   // ---------- grain tile ----------
107|   let grainCanvas = null;
108|   function buildGrain() {
109|     const size = 128;
110|     grainCanvas = document.createElement("canvas");
111|     grainCanvas.width = size;
112|     grainCanvas.height = size;
113|     const gctx = grainCanvas.getContext("2d");
114|     const imgData = gctx.createImageData(size, size);
115|     for (let i = 0; i < imgData.data.length; i += 4) {
116|       const v = Math.random() * 255;
117|       imgData.data[i] = v;
118|       imgData.data[i + 1] = v;
119|       imgData.data[i + 2] = v;
120|       imgData.data[i + 3] = 255;
121|     }
122|     gctx.putImageData(imgData, 0, 0);
123|   }
124|   buildGrain();
125| 
126|   function resize() {
127|     dpr = Math.max(1, window.devicePixelRatio || 1);
128|     W = window.innerWidth;
129|     H = window.innerHeight;
130|     canvas.width = Math.round(W * dpr);
131|     canvas.height = Math.round(H * dpr);
132|     canvas.style.width = W + "px";
133|     canvas.style.height = H + "px";
134|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
135|     draw();
136|   }
137|   window.addEventListener("resize", resize);
138| 
139|   // ---------- sand raked lines ----------
140|   function drawSand() {
141|     ctx.fillStyle = "#fbf7ee";
142|     ctx.fillRect(0, 0, W, H);
143| 
144|     ctx.save();
145|     ctx.strokeStyle = "#0078bf";
146|     ctx.globalAlpha = 0.18;
147|     ctx.lineWidth = 1.5;
148|     const spacing = 22;
149|     for (let y = -H; y < H * 2; y += spacing) {
150|       ctx.beginPath();
151|       for (let x = -20; x <= W + 20; x += 14) {
152|         const wob = Math.sin((x + y) * 0.04) * 5;
153|         if (x === -20) ctx.moveTo(x, y + wob);
154|         else ctx.lineTo(x, y + wob);
155|       }
156|       ctx.stroke();
157|     }
158|     ctx.restore();
159|   }
160| 
161|   function drawStone(p) {
162|     ctx.save();
163|     ctx.translate(p.x, p.y);
164|     ctx.rotate(p.rot);
165| 
166|     // ripple rings, ink two
167|     ctx.save();
168|     ctx.strokeStyle = "#0078bf";
169|     ctx.globalAlpha = 0.35;
170|     ctx.lineWidth = 1.5;
171|     for (let i = 1; i <= 3; i++) {
172|       ctx.beginPath();
173|       ctx.ellipse(1, 1, p.r + i * 9, p.r * 0.55 + i * 5, 0, 0, Math.PI * 2);
174|       ctx.stroke();
175|     }
176|     ctx.restore();
177| 
178|     // stone shadow offset (misregistration) - ink two layer
179|     ctx.save();
180|     ctx.fillStyle = "#0078bf";
181|     ctx.globalAlpha = 0.55;
182|     ctx.beginPath();
183|     ctx.ellipse(2, 3, p.r, p.r * 0.72, 0, 0, Math.PI * 2);
184|     ctx.fill();
185|     ctx.restore();
186| 
187|     // stone body - ink one or overlap
188|     ctx.save();
189|     ctx.fillStyle = p.shade ? "#ff48b0" : "#5b3a8c";
190|     ctx.beginPath();
191|     ctx.ellipse(0, 0, p.r * 0.96, p.r * 0.68, 0, 0, Math.PI * 2);
192|     ctx.fill();
193|     ctx.restore();
194| 
195|     // halftone dots
196|     ctx.save();
197|     ctx.fillStyle = "#5b3a8c";
198|     ctx.globalAlpha = 0.5;
199|     for (let i = 0; i < 6; i++) {
200|       const ang = (i / 6) * Math.PI * 2;
201|       const dx = Math.cos(ang) * p.r * 0.5;
202|       const dy = Math.sin(ang) * p.r * 0.32;
203|       ctx.beginPath();
204|       ctx.arc(dx, dy, 1.6, 0, Math.PI * 2);
205|       ctx.fill();
206|     }
207|     ctx.restore();
208| 
209|     ctx.restore();
210|   }
211| 
212|   function drawGrain() {
213|     if (!grainCanvas) return;
214|     ctx.save();
215|     ctx.globalAlpha = 0.08;
216|     const pattern = ctx.createPattern(grainCanvas, "repeat");
217|     ctx.fillStyle = pattern;
218|     ctx.fillRect(0, 0, W, H);
219|     ctx.restore();
220|   }
221| 
222|   function drawTitleHint() {
223|     ctx.save();
224|     ctx.textAlign = "center";
225|     ctx.textBaseline = "middle";
226| 
227|     const pulse = 0.7 + 0.3 * Math.sin(Date.now() / 350);
228| 
229|     ctx.font = "900 34px 'Arial Narrow', Arial, sans-serif";
230|     ctx.fillStyle = "#0078bf";
231|     ctx.globalAlpha = 0.9;
232|     ctx.fillText("JARDIN DE CAILLOUX", W / 2 + 2, H / 2 - 40 + 2);
233|     ctx.fillStyle = "#ff48b0";
234|     ctx.fillText("JARDIN DE CAILLOUX", W / 2, H / 2 - 40);
235| 
236|     ctx.globalAlpha = pulse;
237|     ctx.font = "700 18px 'Arial Narrow', Arial, sans-serif";
238|     ctx.fillStyle = "#5b3a8c";
239|     ctx.fillText("Touchez l'écran pour commencer", W / 2, H / 2 + 10);
240|     ctx.restore();
241|   }
242| 
243|   function draw() {
244|     drawSand();
245|     for (const p of pieces) drawStone(p);
246|     if (!running) drawTitleHint();
247|     drawGrain();
248|   }
249| 
250|   function updateTally() {
251|     tallyEl.textContent = "Cailloux : " + tally;
252|   }
253| 
254|   function place(x, y) {
255|     const r = 16 + Math.random() * 14;
256|     pieces.push({
257|       x, y, r,
258|       rot: (Math.random() - 0.5) * 1.2,
259|       shade: Math.random() > 0.4,
260|     });
261|     tally += 1;
262|     updateTally();
263|     CARTRIDGE.send("score", { value: tally });
264|   }
265| 
266|   // Single clear-the-table function: called by the visible button
267|   // AND by the host reset command directly (no indirection).
268|   function clearTable() {
269|     pieces.length = 0;
270|     tally = 0;
271|     updateTally();
272|     CARTRIDGE.send("score", { value: 0 });
273|     draw();
274|   }
275| 
276|   clearBtn.addEventListener("click", clearTable);
277| 
278|   // ---------- input ----------
279|   canvas.style.touchAction = "none";
280|   canvas.addEventListener("pointerdown", (event) => {
281|     event.preventDefault();
282|     if (paused) return;
283|     if (!running) {
284|       running = true;
285|       CARTRIDGE.send("start");
286|       draw();
287|       return;
288|     }
289|     const rect = canvas.getBoundingClientRect();
290|     const x = event.clientX - rect.left;
291|     const y = event.clientY - rect.top;
292|     place(x, y);
293|     draw();
294|   });
295| 
296|   // ---------- host messages ----------
297|   window.addEventListener("message", (event) => {
298|     const data = event.data;
299|     if (!data || data.source !== "cartridge-host") return;
300|     if (data.type === "pause") paused = true;
301|     if (data.type === "resume") paused = false;
302|     if (data.type === "reset") {
303|       running = false;
304|       clearTable();
305|     }
306|   });
307| 
308|   // ---------- loop ----------
309|   function frame() {
310|     if (!paused) draw();
311|     requestAnimationFrame(frame);
312|   }
313| 
314|   resize();
315|   updateTally();
316|   CARTRIDGE.send("boot", { title: "Jardin de Cailloux", gameType: "toy-box", lang: "fr" });
317|   requestAnimationFrame(frame);
318| })();
319| </script>
320| </body>
321| </html>
